transforms.code:
security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['configureLots']['enabled']: 
		canCreate = True
		canEdit = True if len(value['data']) > 0 else False

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}

config.script:
if self.view.custom.lotOperations.userAction.canUpdate:
	lotOperationId = self.props.data[event.row]['lotOperationId']

	if event.column in ('enabled', 'lotOperationName', 'lotOperationColor', 'allowInputLots', 'allowOutputLots'):
		retVal, msg = system.kanoa.lot.updateLotOperationField(lotOperationId, event.column, event.value, self.view.custom.security.userId)

		if msg: system.perspective.sendMessage('showFailerToast', {'message': 'Failed to update the lot Operation. %s'%msg})
		else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Lot Operation has been updated'})		
	else:
		system.perspective.sendMessage('showFailerToast', 'Column is not enabled for editing')
else:
	system.perspective.sendMessage('showFailerToast', 'No permissions to update lot operations')

self.view.refreshBinding("custom.lotOperations.data")
self.props.selection.selectedRow = None	
self.props.selection.selectedCol = None	

return

